package com.bettergoldsmithing;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BetterGoldsmithingConfig.GROUP)
public interface BetterGoldsmithingConfig extends Config
{
	String GROUP = "better-goldsmithing";

	@ConfigItem(
		keyName = "blockDepositWithoutGauntlets",
		name = "Block deposit without gauntlets",
		description = "Prevent putting gold ore on the Blast Furnace conveyor unless Gauntlets of goldsmithing are equipped.",
		position = 1
	)
	default boolean blockDepositWithoutGauntlets()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lockGloves",
		name = "Lock gloves until smelted",
		description = "After depositing gold ore with gauntlets on, block equipping/removing gloves until the whole batch has finished smelting (all of its bonus XP credited).",
		position = 2
	)
	default boolean lockGloves()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showLockIcon",
		name = "Show lock icon on gloves",
		description = "While the glove slot is locked, draw a small 🚫 mark on any gloves in your inventory so the lock is obvious at a glance.",
		position = 3
	)
	default boolean showLockIcon()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideEmptyDispenser",
		name = "Hide empty dispenser option",
		description = "Remove the bar dispenser's left-click option while it's empty (shows \"Check\" instead of \"Take\"), so you can't waste a click collecting nothing.",
		position = 4
	)
	default boolean hideEmptyDispenser()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showChatMessages",
		name = "Show chat warnings",
		description = "Print a game message when a deposit or glove swap is blocked.",
		position = 5
	)
	default boolean showChatMessages()
	{
		return true;
	}

	@Range(min = 0, max = 200)
	@ConfigItem(
		keyName = "maxLockTicks",
		name = "Safety auto-unlock (ticks)",
		description = "Release the glove lock if there is no smelting progress for this many game ticks, so you can never get stuck (the timer resets while bars are still smelting). 0 disables the safety net.",
		position = 6
	)
	default int maxLockTicks()
	{
		return 50;
	}
}

package com.bettergoldsmithing;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Arrays;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Skill;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Better Goldsmithing",
	description = "Stops you depositing gold ore without goldsmith gauntlets, and locks your glove slot until the Smithing XP lands so you never lose the bonus.",
	tags = {"blast", "furnace", "goldsmith", "gauntlets", "smithing", "gold"}
)
public class BetterGoldsmithingPlugin extends Plugin
{
	private static final int GLOVE_SLOT = EquipmentInventorySlot.GLOVES.getSlotIdx();

	// Menu option text for putting on / taking off worn equipment.
	private static final Set<String> EQUIP_OPTIONS = Set.of("wear", "wield", "equip");
	private static final Set<String> REMOVE_OPTIONS = Set.of("remove", "take-off");

	// Object actions that can carry the conveyor "Put-ore" interaction.
	private static final Set<MenuAction> OBJECT_ACTIONS = Set.of(
		MenuAction.GAME_OBJECT_FIRST_OPTION,
		MenuAction.GAME_OBJECT_SECOND_OPTION,
		MenuAction.GAME_OBJECT_THIRD_OPTION,
		MenuAction.GAME_OBJECT_FOURTH_OPTION,
		MenuAction.GAME_OBJECT_FIFTH_OPTION
	);

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BetterGoldsmithingConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GloveLockOverlay gloveLockOverlay;

	// True while we are protecting the glove slot, i.e. between depositing gold
	// ore with gauntlets on and the whole batch finishing smelting (all the
	// Smithing XP credited). At the Blast Furnace the XP is granted as the bars
	// smelt, which the BLAST_FURNACE_GOLD_ORE varbit tracks (it counts down to 0
	// as the deposited ore is converted), so we hold the lock until it hits 0.
	private boolean glovesLocked;
	private int lastSmithingXp;
	private int lockTicksRemaining;
	// True once the deposited ore has actually shown up in the furnace, so a
	// momentary 0 right after depositing (ore still on the belt) can't release
	// the lock early.
	private boolean oreEnteredFurnace;

	// True while the Blast Furnace conveyor is loaded in the scene (i.e. we're at
	// the furnace). Lets a gold deposit be told apart from gold ore leaving the
	// inventory anywhere else. Tracked via game object (de)spawn.
	private boolean conveyorInScene;
	// Whether the inventory held gold ore at the previous change, so we can detect
	// the present -> gone transition that means a deposit just completed.
	private boolean prevInvHadGoldOre;

	// Mirrors the furnace's gold-ore count so a rise (a deposit) can arm the lock
	// even if the deposit click was missed. -1 means "not yet observed".
	private int lastFurnaceGoldOre = -1;

	@Override
	protected void startUp()
	{
		clearLock();
		overlayManager.add(gloveLockOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(gloveLockOverlay);
		clearLock();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Order matters: a deposit click should arm the lock, not be blocked by it.
		handleConveyorDeposit(event);

		if (!event.isConsumed())
		{
			handleGloveLock(event);
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		final String option = event.getOption();

		// An empty bar dispenser offers "Check"; once bars are ready it becomes
		// "Take". Drop the "Check" entry so the empty dispenser isn't clickable
		// and you can't waste a tick collecting nothing.
		if (config.hideEmptyDispenser()
			&& "Check".equalsIgnoreCase(option)
			&& "Bar dispenser".equalsIgnoreCase(Text.removeTags(event.getTarget())))
		{
			removeLastMenuEntry();
			return;
		}

		// Remove the conveyor's deposit ("Put-ore") option while gold ore is in
		// the inventory without the gauntlets on. The conveyor only has the one
		// object interaction, so we match on the action type rather than the
		// option text. Left-click then falls through to "Walk here", so a click
		// just walks you to the belt instead of depositing the gold and losing
		// the bonus XP.
		if (config.blockDepositWithoutGauntlets()
			&& event.getIdentifier() == ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE
			&& OBJECT_ACTIONS.contains(event.getMenuEntry().getType())
			&& inventoryHasGoldOre()
			&& !goldsmithGauntletsEquipped())
		{
			removeLastMenuEntry();
		}
	}

	// onMenuEntryAdded fires right after the entry is appended, so the entry we
	// want to drop is the last element of the current menu.
	private void removeLastMenuEntry()
	{
		final MenuEntry[] entries = client.getMenuEntries();
		if (entries.length > 0)
		{
			client.setMenuEntries(Arrays.copyOf(entries, entries.length - 1));
		}
	}

	private void handleConveyorDeposit(MenuOptionClicked event)
	{
		if (!OBJECT_ACTIONS.contains(event.getMenuAction()))
		{
			return;
		}

		if (event.getId() != ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE)
		{
			return;
		}

		// The conveyor only deposits ore; "Put-ore" empties all ores from the
		// inventory. We only care when that batch includes gold ore.
		if (!inventoryHasGoldOre())
		{
			return;
		}

		final boolean gauntlets = goldsmithGauntletsEquipped();

		if (!gauntlets)
		{
			// The "Put-ore" option is normally stripped in onMenuEntryAdded, so
			// this is just a backstop in case a deposit click slips through.
			if (config.blockDepositWithoutGauntlets())
			{
				event.consume();
			}
			return;
		}

		// Gauntlets are on, so nothing to block here. The lock arms in
		// onItemContainerChanged the instant the gold ore leaves the inventory.
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		final boolean hasGold = containerHasGoldOre(event.getItemContainer());
		final boolean justEmptied = prevInvHadGoldOre && !hasGold;
		prevInvHadGoldOre = hasGold;

		// Gold ore went from present to gone while we're at the furnace with the
		// gauntlets on: a deposit just completed. Arm immediately, the instant the
		// inventory empties, independent of whether the deposit click was caught.
		// That click handoff is occasionally missed, which used to leave the lock
		// waiting on the belt-delayed varbit fallback (the lag you saw).
		// The bank check excludes banking gold ore (also empties it, but with the
		// bank open) from being mistaken for a conveyor deposit.
		if (!glovesLocked && justEmptied && config.lockGloves()
			&& conveyorInScene && goldsmithGauntletsEquipped() && !bankOpen())
		{
			armLock("inventory emptied");
		}
	}

	// A conveyor deposit happens with the bank closed; depositing gold ore into
	// the bank happens with it open. Used to tell the two apart.
	private boolean bankOpen()
	{
		final Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		return bank != null && !bank.isHidden();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		final GameObject go = event.getGameObject();
		if (go.getId() == ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE)
		{
			conveyorInScene = true;
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		final GameObject go = event.getGameObject();
		if (go.getId() == ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE)
		{
			conveyorInScene = false;
		}
	}

	// While locked, block equipping OR removing anything that occupies the glove
	// slot. This is deliberately not a hardcoded ID list: it covers ice gloves,
	// Smiths gloves (i), and any future gloves Jagex add, since the slot is read
	// from the client's own item data (see isGloveSlotItem).
	private void handleGloveLock(MenuOptionClicked event)
	{
		if (!glovesLocked)
		{
			return;
		}

		final String option = event.getMenuOption() == null
			? ""
			: event.getMenuOption().toLowerCase();

		final boolean equipping = EQUIP_OPTIONS.contains(option);
		final boolean removing = REMOVE_OPTIONS.contains(option);
		if (!equipping && !removing)
		{
			return;
		}

		final int itemId = event.getItemId();
		if (itemId <= 0 || !isGloveSlotItem(itemId))
		{
			return;
		}

		event.consume();
		warn("Gloves are locked until your deposited gold finishes smelting.");
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!glovesLocked || event.getSkill() != Skill.SMITHING)
		{
			return;
		}

		// A Smithing XP gain means a bar just smelted, i.e. the batch is still
		// being worked. Don't release here (more bars may still be smelting);
		// just treat it as progress and push back the safety timeout.
		if (event.getXp() > lastSmithingXp)
		{
			lastSmithingXp = event.getXp();
			lockTicksRemaining = config.maxLockTicks();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.BLAST_FURNACE_GOLD_ORE)
		{
			return;
		}

		final int value = event.getValue();
		final int previous = lastFurnaceGoldOre;
		lastFurnaceGoldOre = value;

		if (glovesLocked)
		{
			if (value > 0)
			{
				// Deposited ore is in the furnace and smelting; keep holding.
				oreEnteredFurnace = true;
				lockTicksRemaining = config.maxLockTicks();
			}
			else if (oreEnteredFurnace)
			{
				// Gold ore in the furnace has reached 0: the whole batch has
				// finished smelting, so all of its bonus XP has now been credited
				// with the gauntlets on. Safe to release.
				releaseLock("gold batch finished smelting");
			}
			return;
		}

		// Not locked: a rise in the furnace's gold ore means a deposit just
		// landed. Arm here as a focus-independent fallback, in case the deposit
		// click was never seen (the menu/click path can be missed, e.g. around
		// window focus changes). previous >= 0 skips the first observation so a
		// stale value can't look like a deposit.
		if (previous >= 0 && value > previous
			&& config.lockGloves() && goldsmithGauntletsEquipped())
		{
			armLock("furnace varbit fallback");
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!glovesLocked || config.maxLockTicks() <= 0)
		{
			return;
		}

		if (--lockTicksRemaining <= 0)
		{
			releaseLock("safety timeout reached without smelting progress");
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN
			|| state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			clearLock();
			// Re-baseline the trackers so stale values from before the world
			// change can't look like a fresh deposit after logging in.
			lastFurnaceGoldOre = -1;
			conveyorInScene = false;
			prevInvHadGoldOre = false;
		}
	}

	private void armLock(String via)
	{
		glovesLocked = true;
		lastSmithingXp = client.getSkillExperience(Skill.SMITHING);
		lockTicksRemaining = config.maxLockTicks();
		// If the ore already registered in the furnace this same tick, note it so
		// the lock can release once it smelts back down to 0.
		oreEnteredFurnace = client.getVarbitValue(VarbitID.BLAST_FURNACE_GOLD_ORE) > 0;
		log.debug("Glove lock armed via {}", via);
	}

	private void releaseLock(String reason)
	{
		clearLock();
		// Diagnostic only - releasing the lock is expected and must not spam chat.
		log.debug("Glove lock released: {}", reason);
	}

	private void clearLock()
	{
		glovesLocked = false;
		lastSmithingXp = 0;
		lockTicksRemaining = 0;
		oreEnteredFurnace = false;
	}

	private boolean inventoryHasGoldOre()
	{
		return containerHasGoldOre(client.getItemContainer(InventoryID.INV));
	}

	private boolean containerHasGoldOre(ItemContainer container)
	{
		if (container == null)
		{
			return false;
		}

		for (final Item item : container.getItems())
		{
			if (item.getId() == ItemID.GOLD_ORE)
			{
				return true;
			}
		}
		return false;
	}

	private boolean goldsmithGauntletsEquipped()
	{
		final ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}

		final Item gloves = equipment.getItem(GLOVE_SLOT);
		return gloves != null && gloves.getId() == ItemID.GAUNTLETS_OF_GOLDSMITHING;
	}

	// True while the glove slot is being protected; read by GloveLockOverlay.
	boolean isGloveLockActive()
	{
		return glovesLocked;
	}

	// Returns true for any item worn in the glove slot, determined from the
	// client's item database rather than a fixed list - so new gloves are
	// covered automatically.
	boolean isGloveSlotItem(int itemId)
	{
		final ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null
			&& stats.getEquipment() != null
			&& stats.getEquipment().getSlot() == GLOVE_SLOT;
	}

	private void warn(String message)
	{
		if (!config.showChatMessages())
		{
			return;
		}

		client.addChatMessage(
			ChatMessageType.GAMEMESSAGE,
			"",
			ColorUtil.wrapWithColorTag("[Better Goldsmithing] " + message, Color.RED),
			null);
	}

	@Provides
	BetterGoldsmithingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BetterGoldsmithingConfig.class);
	}
}

package com.bettergoldsmithing;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Draws a small, semi-transparent "no entry" mark on every glove in the
 * inventory while the glove slot is locked, so the lock is obvious at a glance.
 */
class GloveLockOverlay extends WidgetItemOverlay
{
	private final BetterGoldsmithingPlugin plugin;
	private final BetterGoldsmithingConfig config;

	@Inject
	GloveLockOverlay(BetterGoldsmithingPlugin plugin, BetterGoldsmithingConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showLockIcon() || !plugin.isGloveLockActive() || !plugin.isGloveSlotItem(itemId))
		{
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		final int d = 13;
		final int x = bounds.x + bounds.width - d - 1;
		final int y = bounds.y + 1;
		final double inset = d * 0.15;

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.65f));
			g.setStroke(new BasicStroke(2f));
			g.setColor(Color.RED);
			g.drawOval(x, y, d, d);
			g.drawLine(
				(int) Math.round(x + inset), (int) Math.round(y + inset),
				(int) Math.round(x + d - inset), (int) Math.round(y + d - inset));
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.bettergoldsmithing;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BetterGoldsmithingPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BetterGoldsmithingPlugin.class);
		RuneLite.main(args);
	}
}
